import {
  POS_NEGATIVE_BAR_DATALABEL_CLEARANCE_PX,
  POS_POSITIVE_BAR_DATALABEL_CLEARANCE_PX,
  POS_POSITIVE_DATALABEL_HEADROOM_PX,
} from '../constants';
import type { PosPerformanceBarDataset } from '../types/index';

export const POS_Y_PAD_BEYOND_EXTREME_BAR_PCT = 0.72;

export const POS_Y_AXIS_MIN_EXTENT_PCT = 1;

export const POS_BAR_BLEED_GAP_PX = 6;

export const POS_ZERO_LINE_OFFSET_ABOVE_CENTER_PX = 10;

export const POS_CHART_Y_PLOT_HEIGHT_ESTIMATE_PX = 285;

export type SymmetricYScaleOptions = {
  plotHeightPx?: number;
  zeroLineOffsetAboveCenterPx?: number;
};

export function getBarValueExtents(
  datasets: readonly PosPerformanceBarDataset[],
): { min: number | null; max: number | null } {
  let min: number | null = null;
  let max: number | null = null;

  for (const ds of datasets) {
    for (const raw of ds.data) {
      const v = typeof raw === 'number' ? raw : Number(raw);
      if (!Number.isFinite(v)) continue;
      if (min === null || v < min) min = v;
      if (max === null || v > max) max = v;
    }
  }

  return { min, max };
}

function pxToExtentPadding(
  px: number,
  plotHeightPx: number,
  halfExtent: number,
): number {
  return (px / plotHeightPx) * 2 * halfExtent;
}

function getBleedGapPx(hasNegative: boolean, hasPositive: boolean): number {
  const labelClearancePx = Math.max(
    hasNegative ? POS_NEGATIVE_BAR_DATALABEL_CLEARANCE_PX : 0,
    hasPositive ? POS_POSITIVE_BAR_DATALABEL_CLEARANCE_PX : 0,
  );

  if (labelClearancePx === 0) {
    return 0;
  }

  return POS_BAR_BLEED_GAP_PX + labelClearancePx;
}

export function getZeroLineAdjustedPositiveExtent(
  negativeHalfExtent: number,
  plotHeightPx: number,
  offsetAboveCenterPx: number = POS_ZERO_LINE_OFFSET_ABOVE_CENTER_PX,
): number {
  if (
    offsetAboveCenterPx <= 0 ||
    plotHeightPx <= 0 ||
    negativeHalfExtent <= 0
  ) {
    return negativeHalfExtent;
  }

  const targetFractionFromTop = 0.5 - offsetAboveCenterPx / plotHeightPx;
  if (targetFractionFromTop <= 0 || targetFractionFromTop >= 0.5) {
    return negativeHalfExtent;
  }

  return (
    (targetFractionFromTop * negativeHalfExtent) / (1 - targetFractionFromTop)
  );
}

export function getSymmetricYScaleExtents(
  datasets: readonly PosPerformanceBarDataset[],
  options?: SymmetricYScaleOptions,
): { min: number; max: number } {
  const plotHeightPx =
    options?.plotHeightPx ?? POS_CHART_Y_PLOT_HEIGHT_ESTIMATE_PX;
  const { min: dataMin, max: dataMax } = getBarValueExtents(datasets);

  const hasNegative = dataMin !== null && dataMin < 0;
  const hasPositive = dataMax !== null && dataMax > 0;

  let extentBelow = POS_Y_AXIS_MIN_EXTENT_PCT;
  let extentAbove = POS_Y_AXIS_MIN_EXTENT_PCT;

  if (hasNegative) {
    extentBelow = Math.abs(dataMin) + POS_Y_PAD_BEYOND_EXTREME_BAR_PCT;
  }

  if (hasPositive) {
    extentAbove = dataMax + POS_Y_PAD_BEYOND_EXTREME_BAR_PCT;
  }

  let extent = Math.max(extentBelow, extentAbove, POS_Y_AXIS_MIN_EXTENT_PCT);

  const bleedGapPx = getBleedGapPx(hasNegative, hasPositive);
  if (bleedGapPx > 0) {
    extent += pxToExtentPadding(bleedGapPx, plotHeightPx, extent);
  }

  if (hasPositive && dataMax !== null) {
    const positiveLabelHeadroomPct = pxToExtentPadding(
      POS_POSITIVE_DATALABEL_HEADROOM_PX,
      plotHeightPx,
      extent,
    );
    extentAbove += positiveLabelHeadroomPct;
    extent = Math.max(extent, extentAbove);
  }

  const offsetMax = getZeroLineAdjustedPositiveExtent(
    extent,
    plotHeightPx,
    options?.zeroLineOffsetAboveCenterPx ??
      POS_ZERO_LINE_OFFSET_ABOVE_CENTER_PX,
  );

  const cappedMax = Math.min(extent, offsetMax);
  const max = hasPositive ? Math.max(extentAbove, cappedMax) : cappedMax;

  return { min: -extent, max };
}
